(()=>{'use strict';const s=document.querySelector('.cinema'),$=q=>s.querySelector(q),stage=$('.cinema-stage'),photos=[...s.querySelectorAll('.cinema-photo')],steps=[...s.querySelectorAll('[data-cinema-step]')],reduce=matchMedia('(prefers-reduced-motion:reduce)'),stops=[0,.23,.46,.70,.94];let frame=0,previous=-1,sent=false;
const scenes=[['Client discussions.','Alex is preparing a product launch. He meets the client, visits the venue, and discusses the revised proposal over dinner.','Double-press to start and end recording.\nPress once to mark a moment.'],['Venue constraints.','A narrow entrance. A shorter setup window. Alex marks the details while staying in the conversation.','“We need the revised proposal by Friday.”\n“Check the entrance and setup window.”'],['Connect your AI.','Back at the hotel, Alex syncs Vocci and asks his connected ChatGPT to organize actions by team. He reviews them, adds owners, then shares.',''],['Ask Vocci AI.','On the way to the airport, Alex holds the ring to ask Maya for an initial assessment of the venue constraints.',''],['Review in Vocci AI.','Alex checks the recipient and message in the App before it is sent through the connected Slack.','']];const ringPoints=[[.585,.466],[.625,.694],[.460,.505]];
function render(){frame=0;const r=s.getBoundingClientRect(),p=Math.max(0,Math.min(1,-r.top/Math.max(1,s.offsetHeight-stage.offsetHeight))),beat=p<.13?0:p<.35?1:p<.59?2:p<.83?3:4,a=p<.35?0:p<.59?1:2;
photos.forEach((im,j)=>{let opacity=j===a?1:0;if(p>.30&&p<.40){const b=(p-.30)/.1;opacity=j===0?1-b:j===1?b:0}if(p>.54&&p<.64){const b=(p-.54)/.1;opacity=j===1?1-b:j===2?b:0}im.style.opacity=opacity;im.style.filter=reduce.matches?'none':`blur(${(1-opacity)*12}px)`;const base=[2.75,1.65,2.4][j],z=reduce.matches?base:base+p*.15,w=im.clientWidth,h=im.clientHeight,iw=Math.min(w,h*1.5),ih=iw/1.5,rp=ringPoints[j],rx=(w-iw)/2+iw*rp[0],ry=h-ih+ih*rp[1];im.style.transform=`translate(${w*.51-z*rx}px,${h*.50-z*ry}px) scale(${z})`;});
if(beat!==previous){previous=beat;s.dataset.scene=beat;$('#cinema-title').textContent=sent&&beat===4?'Maya receives the message.':scenes[beat][0];$('#cinema-body').textContent=scenes[beat][1];$('#cinema-support-line').innerText=scenes[beat][2];$('#cinema-context').hidden=beat>1;$('#cinema-brief').hidden=beat!==2;$('#cinema-app').hidden=beat<3;$('.cinema-send').hidden=beat!==4||sent;$('#cinema-sent').hidden=beat!==4||!sent;steps.forEach((b,k)=>{if(k===beat)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});const active=steps[beat],nav=active.parentElement;if(nav.scrollWidth>nav.clientWidth)nav.scrollTo({left:active.offsetLeft-nav.offsetLeft-16,behavior:reduce.matches?'instant':'smooth'});}
const ir=photos[a].getBoundingClientRect(),sr=stage.getBoundingClientRect(),iw=Math.min(ir.width,ir.height*1.5),ih=iw/1.5,point=ringPoints[a];$('.cinema-focal').style.left=((ir.left+(ir.width-iw)/2+iw*point[0]-sr.left)/sr.width*100)+'%';$('.cinema-focal').style.top=((ir.bottom-ih+ih*point[1]-sr.top)/sr.height*100)+'%';$('.cinema-timeline i').style.width=p*100+'%';const entry=Math.max(0,Math.min(1,1-r.top/innerHeight));stage.style.setProperty('--entry-scale',reduce.matches?1:.94+.06*entry);stage.style.setProperty('--entry-radius',(1-entry)*28+'px')}
function queue(){if(!frame)frame=requestAnimationFrame(render)}addEventListener('scroll',queue,{passive:true});addEventListener('resize',queue);reduce.addEventListener('change',queue);photos.forEach(im=>im.addEventListener('load',queue));steps.forEach(b=>b.addEventListener('click',()=>scrollTo({top:s.getBoundingClientRect().top+scrollY+stops[+b.dataset.cinemaStep]*(s.offsetHeight-stage.offsetHeight),behavior:reduce.matches?'instant':'smooth'})));const dialog=document.querySelector('#cinema-review-dialog');$('#cinema-review').addEventListener('click',()=>dialog.showModal());document.querySelector('#cinema-close').addEventListener('click',()=>dialog.close());$('#cinema-send').addEventListener('click',()=>{sent=true;previous=-1;render()});render()})();
